import { readFileSync } from "node:fs";
import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import TokenSwatch from "./TokenSwatch.js";

describe("TokenSwatch SSR", () => {
  it("renders both values inline and the mode names on the server", () => {
    const html = renderToString(<TokenSwatch dark="#262626" light="#ffffff" />);
    expect(html).toContain('class="ds token-swatch"');
    expect(html).toContain('style="--token-swatch-value:#ffffff"');
    expect(html).toContain('style="--token-swatch-value:#262626"');
    expect(html).toContain(">Light</span>");
    expect(html).toContain(">Dark</span>");
  });

  it("names no colour of its own and sets no name on the token's colour", () => {
    const styles = readFileSync(
      new URL("./styles.css", import.meta.url),
      "utf8",
    );
    expect(styles).toMatch(
      /\.ds\.token-swatch \.value \{[^}]*background: var\(--token-swatch-value\);/,
    );
    expect(styles).toMatch(
      /\.ds\.token-swatch \.mode \{[^}]*color: var\(--token-swatch-label-color\);/,
    );
    expect(styles).not.toMatch(/#[0-9a-f]{3,8}\b|rgb\(|hsl\(/i);
  });
});
